8	public class SeedDataImporter(AppDbContext db)
9	{
10	    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };
11	
12	    public async Task ImportIfEmptyAsync(string jsonFilePath, CancellationToken ct = default)
13	    {
14	        if (await db.Venues.AnyAsync(ct))
15	        {
16	            return;
17	        }
18	
19	        if (!File.Exists(jsonFilePath))
20	        {
21	            throw new InvalidOperationException($"Anfangsdatenbestand '{jsonFilePath}' wurde nicht gefunden.");
22	        }
23	
24	        var json = await File.ReadAllTextAsync(jsonFilePath, ct);
25	        SeedDataDto? data;
26	        try
27	        {
28	            data = JsonSerializer.Deserialize<SeedDataDto>(json, JsonOptions);
29	        }
30	        catch (JsonException ex)
31	        {
32	            throw new InvalidOperationException($"Anfangsdatenbestand '{jsonFilePath}' enthält kein gültiges JSON.", ex);
33	        }
34	
35	        if (data is null)
36	        {
37	            throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{jsonFilePath}' gelesen werden.");
38	        }
39	
40	        await ImportAsync(data, ct);
41	    }
42	
43	    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
44	    {
45	        var spielstaetten = data.Spielstaetten
46	            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'spielstaetten'-Feld.");
47	        var veranstaltungen = data.Veranstaltungen
48	            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'veranstaltungen'-Feld.");
49	
50	        var venueIds = new HashSet<string>();
51	        foreach (var venueDto in spielstaetten)
52	        {
53	            if (!venueIds.Add(venueDto.Id))
54	            {
55	                throw new InvalidOperationException($"Spielstätte '{venueDto.Id}' ist im Anfangsdatenbestand mehrfach vorhanden.");
56	            }
57	        }
58	
59	        foreach (var eventDto in veranstaltungen)
60	        {
61	            if (!venueIds.Contains(eventDto.SpielstaetteId))
62	            {
63	                throw new InvalidOperationException(
64	                    $"Veranstaltung '{eventDto.Id}' referenziert unbekannte Spielstätte '{eventDto.SpielstaetteId}'.");
65	            }
66	        }
67	
68	        var venues = new List<Venue>();
69	
70	        foreach (var venueDto in spielstaetten)
71	        {
72	            var venue = new Venue { Name = venueDto.Name };
73	            var roomsById = new Dictionary<string, Room>();
74	
75	            var raeume = venueDto.Raeume
76	                ?? throw new InvalidOperationException($"Spielstätte '{venueDto.Id}' enthält kein 'raeume'-Feld.");
77	
78	            foreach (var roomDto in raeume)
79	            {
80	                var roomId = RequireNonNull(roomDto.Id, $"Spielstätte '{venueDto.Id}' enthält einen Raum mit fehlender (null) Id.");
81	                var roomName = RequireNonNull(roomDto.Name, $"Raum '{roomId}' in Spielstätte '{venueDto.Id}' hat einen fehlenden (null) Namen.");
82	
83	                if (roomDto.Spalten < 1)
84	                {
85	                    throw new InvalidOperationException(
86	                        $"Raum '{roomId}' in Spielstätte '{venueDto.Id}' hat eine ungültige Spaltenzahl ({roomDto.Spalten}); erwartet wird mindestens 1.");
87	                }
88	
89	                var aisleColumns = roomDto.Gang?.Spalten ?? new List<int>();
90	                foreach (var column in aisleColumns)
91	                {
92	                    if (column < 1 || column > roomDto.Spalten)
93	                    {
94	                        throw new InvalidOperationException(
95	                            $"Raum '{roomId}': Gang-Spalte '{column}' liegt außerhalb des Sitzplans (1..{roomDto.Spalten}).");
96	                    }
97	                }
98	
99	                if (!roomsById.TryAdd(roomId, new Room
100	                {
101	                    Name = roomName,
102	                    RowLabels = roomDto.Reihen ?? new List<string>(),
103	                    ColumnCount = roomDto.Spalten,
104	                    AisleColumns = aisleColumns,
105	                }))
106	                {
107	                    throw new InvalidOperationException(
108	                        $"Spielstätte '{venueDto.Id}' enthält den Raum '{roomId}' mehrfach.");
109	                }
110	
111	                venue.Rooms.Add(roomsById[roomId]);
112	            }
113	
114	            foreach (var eventDto in veranstaltungen.Where(e => e.SpielstaetteId == venueDto.Id))
115	            {
116	                var raumId = RequireNonNull(eventDto.RaumId, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Raum-Id.");
117	                if (!roomsById.TryGetValue(raumId, out var room))
118	                {
119	                    throw new InvalidOperationException(
120	                        $"Veranstaltung '{eventDto.Id}' referenziert unbekannten Raum '{raumId}' in Spielstätte '{venueDto.Id}'.");
121	                }
122	
123	                if (eventDto.DauerMinuten < 1)
124	                {
125	                    throw new InvalidOperationException(
126	                        $"Veranstaltung '{eventDto.Id}' hat eine ungültige Dauer ({eventDto.DauerMinuten} Minuten); erwartet wird mindestens 1.");
127	                }
128	
129	                if (eventDto.Altersfreigabe < 0)
130	                {
131	                    throw new InvalidOperationException(
132	                        $"Veranstaltung '{eventDto.Id}' hat eine ungültige Altersfreigabe ({eventDto.Altersfreigabe}); negative Werte sind nicht erlaubt.");
133	                }
134	
135	                var @event = new Event
136	                {
137	                    Titel = RequireNonNull(eventDto.Titel, $"Veranstaltung '{eventDto.Id}' hat einen fehlenden (null) Titel."),
138	                    Beschreibung = RequireNonNull(eventDto.Beschreibung, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Beschreibung."),
139	                    Zeitpunkt = eventDto.Zeitpunkt,
140	                    DauerMinuten = eventDto.DauerMinuten,
141	                    Altersfreigabe = eventDto.Altersfreigabe,
142	                };
143	
144	                var preiskategorien = eventDto.Preiskategorien
145	                    ?? throw new InvalidOperationException($"Veranstaltung '{eventDto.Id}' enthält kein 'preiskategorien'-Feld.");
146	
147	                foreach (var priceCategoryDto in preiskategorien)
148	                {
149	                    if (priceCategoryDto.Preis < 0)
150	                    {
151	                        throw new InvalidOperationException(
152	                            $"Veranstaltung '{eventDto.Id}': Preiskategorie '{priceCategoryDto.Id}' hat einen negativen Preis ({priceCategoryDto.Preis}).");
153	                    }
154	
155	                    @event.PriceCategories.Add(new PriceCategory
156	                    {
157	                        Name = priceCategoryDto.Name,
158	                        Preis = priceCategoryDto.Preis,
159	                    });
160	                }
161	
162	                var belegteSitzplaetze = eventDto.BelegteSitzplaetze
163	                    ?? throw new InvalidOperationException($"Veranstaltung '{eventDto.Id}' enthält kein 'belegteSitzplaetze'-Feld.");
164	
165	                var gesehen = new HashSet<(string RowLabel, int ColumnNumber)>();
166	                foreach (var sitzplatz in belegteSitzplaetze)
167	                {
168	                    if (sitzplatz is null)
169	                    {
170	                        throw new FormatException(
171	                            $"Veranstaltung '{eventDto.Id}' enthält einen leeren (null) Eintrag in 'belegteSitzplaetze'.");
172	                    }
173	
174	                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);
175	
176	                    if (!gesehen.Add((rowLabel, columnNumber)))
177	                    {
178	                        throw new InvalidOperationException(
179	                            $"Veranstaltung '{eventDto.Id}' listet den Sitzplatz '{sitzplatz}' mehrfach in 'belegteSitzplaetze'.");
180	                    }
181	
182	                    if (!room.RowLabels.Contains(rowLabel))
183	                    {
184	                        throw new InvalidOperationException(
185	                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' referenziert die unbekannte Reihe '{rowLabel}' in Raum '{eventDto.RaumId}'.");
186	                    }
187	
188	                    if (columnNumber < 1 || columnNumber > room.ColumnCount)
189	                    {
190	                        throw new InvalidOperationException(
191	                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt außerhalb der Spaltenzahl (1..{room.ColumnCount}) von Raum '{eventDto.RaumId}'.");
192	                    }
193	
194	                    if (room.AisleColumns.Contains(columnNumber))
195	                    {
196	                        throw new InvalidOperationException(
197	                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt auf einer Gang-Spalte von Raum '{eventDto.RaumId}'.");
198	                    }
199	
200	                    @event.BookingPositions.Add(new BookingPosition
201	                    {
202	                        RowLabel = rowLabel,
203	                        ColumnNumber = columnNumber,
204	                        BookingId = null,
205	                        PriceCategoryId = null,
206	                        CancelledAtUtc = null,
207	                    });
208	                }
209	
210	                room.Events.Add(@event);
211	            }
212	
213	            venues.Add(venue);
214	        }
215	
216	        db.Venues.AddRange(venues);
217	        await db.SaveChangesAsync(ct);
218	    }
219	
220	    /// <summary>
221	    /// `required`-Felder in den Seed-DTOs erzwingen bei System.Text.Json nur die Anwesenheit des
222	    /// JSON-Schlüssels, nicht dessen Nicht-Null-Wert — ein expliziter JSON-`null`-Wert bleibt also
223	    /// trotz `required`-Typisierung zur Laufzeit möglich und würde ohne diese Prüfung zu rohen
224	    /// Ausnahmen (z. B. ArgumentNullException bei Dictionary-Keys) statt einer beschreibenden
225	    /// Fehlermeldung führen.
226	    /// </summary>
227	    private static string RequireNonNull(string? value, string errorMessage) =>
228	        value ?? throw new InvalidOperationException(errorMessage);
229	
230	    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
231	    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
232	    {
233	        var digitsStart = 0;
234	        while (digitsStart < sitzplatz.Length && char.IsAsciiLetter(sitzplatz[digitsStart]))
235	        {
236	            digitsStart++;
237	        }
238	
239	        var digitsEnd = digitsStart;
240	        while (digitsEnd < sitzplatz.Length && char.IsAsciiDigit(sitzplatz[digitsEnd]))
241	        {
242	            digitsEnd++;
243	        }
244	
245	        if (digitsStart == 0 || digitsStart == sitzplatz.Length || digitsEnd != sitzplatz.Length
246	            || !int.TryParse(sitzplatz[digitsStart..], out var columnNumber))
247	        {
248	            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
249	        }
250	
251	        var rowLabel = sitzplatz[..digitsStart];
252	        return (rowLabel, columnNumber);
253	    }
254	}
